	result, err := db.Exec(ctx, "INSERT INTO provider_sync_jobs (   id, provider_connection_id, subject_id, environment_id, status,   date_from, date_to, attempt, max_attempts, available_at,   started_at, finished_at, idempotency_key_hash, request_hash,   idempotency_expires_at, last_error, created_at, updated_at ) SELECT $1::UUID, id, subject_id, environment_id, $3::STRING,   NULLIF($4::STRING, '')::DATE, NULLIF($5::STRING, '')::DATE,   $6::INT4, $7::INT4, $8::TIMESTAMPTZ,   NULLIF($9::STRING, '')::TIMESTAMPTZ,   NULLIF($10::STRING, '')::TIMESTAMPTZ,   $11::BYTES, $12::BYTES,   NULLIF($13::STRING, '')::TIMESTAMPTZ,   $14::STRING, $15::TIMESTAMPTZ, $16::TIMESTAMPTZ FROM provider_connections WHERE id = $2::UUID ON CONFLICT (id) DO UPDATE SET   status = excluded.status,   date_from = excluded.date_from,   date_to = excluded.date_to,   attempt = excluded.attempt,   max_attempts = excluded.max_attempts,   available_at = excluded.available_at,   started_at = excluded.started_at,   finished_at = excluded.finished_at,   idempotency_key_hash = excluded.idempotency_key_hash,   request_hash = excluded.request_hash,   idempotency_expires_at = excluded.idempotency_expires_at,   last_error = excluded.last_error,   created_at = excluded.created_at,   updated_at = excluded.updated_at", P1, Id, P3, P4, P5, P6, P7, P8, P9, P10, P11, P12, P13, P14, P15, P16)
